var a=230;var i=[{id:`cooking-230-01`,theoryId:230,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which fat type is generally recommended to replace saturated fat where practical?`,ua:`Якими жирами зазвичай рекомендують замінювати насичені, коли це можливо?`},explanation:{en:`Replacing some saturated fat with unsaturated fat aligns with common public-health dietary guidance.`,ua:`Часткова заміна насичених жирів ненасиченими відповідає поширеним рекомендаціям зі здорового харчування.`},options:[{id:`a`,text:{en:`Unsaturated fats from suitable plant oils, nuts, or fish`,ua:`Ненасиченими жирами з відповідних рослинних олій, горіхів чи риби`}},{id:`b`,text:{en:`More saturated fat in every recipe`,ua:`Ще більшою кількістю насичених жирів у кожному рецепті`}},{id:`c`,text:{en:`Industrial trans fats`,ua:`Промисловими трансжирами`}}],answer:{optionIds:[`a`]}},{id:`cooking-230-02`,theoryId:230,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Industrially produced trans fats are a recommended source of healthy dietary fat.`,ua:`Промислові трансжири є рекомендованим джерелом корисних жирів.`},explanation:{en:`WHO recommends avoiding industrially produced trans fats.`,ua:`ВООЗ рекомендує уникати промислово вироблених трансжирів.`},answer:{value:!1}},{id:`cooking-230-03`,theoryId:230,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match fat categories to examples.`,ua:`Поєднайте категорії жирів з прикладами.`},explanation:{en:`Fat composition varies by food; many foods contain a mixture of fatty acids.`,ua:`Жировий склад залежить від продукту; багато продуктів містять суміш жирних кислот.`},leftItems:[{id:`l1`,text:{en:`Monounsaturated fats`,ua:`Мононенасичені жири`}},{id:`l2`,text:{en:`Saturated fat`,ua:`Насичені жири`}},{id:`l3`,text:{en:`Industrial trans fats`,ua:`Промислові трансжири`}}],rightItems:[{id:`r2`,text:{en:`Butter is a common source`,ua:`Вершкове масло є поширеним джерелом`}},{id:`r1`,text:{en:`Olive oil is often rich in these`,ua:`Їх часто багато в оливковій олії`}},{id:`r3`,text:{en:`Can arise from partial hydrogenation`,ua:`Можуть утворюватися під час часткової гідрогенізації`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-230-04`,theoryId:230,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A sauce recipe calls for a large amount of butter. You want to reduce saturated fat without losing all richness. What can you test?`,ua:`Соус потребує багато масла. Ви хочете зменшити насичені жири, не втративши насиченості смаку. Що можна перевірити?`},explanation:{en:`Reformulation must consider both nutrition and culinary function.`,ua:`Зміна рецептури має враховувати і харчову цінність, і кулінарну функцію.`},options:[{id:`a`,text:{en:`Remove all liquid and serve dry flour`,ua:`Прибрати всю рідину й подати сухе борошно`}},{id:`b`,text:{en:`Partially replace butter with a suitable unsaturated oil and retest texture`,ua:`Частково замінити масло відповідною ненасиченою олією та перевірити текстуру`}},{id:`c`,text:{en:`Add partially hydrogenated shortening`,ua:`Додати частково гідрогенізований кулінарний жир`}}],answer:{optionIds:[`b`]}},{id:`cooking-230-05`,theoryId:230,type:`multiple_choice`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Which statements about dietary fats are broadly accurate?`,ua:`Які твердження про харчові жири загалом правильні?`},explanation:{en:`Specific fat profiles vary across foods and oils.`,ua:`Конкретний склад жирів відрізняється між продуктами та оліями.`},options:[{id:`a`,text:{en:`All plant oils have identical fat profiles`,ua:`Усі рослинні олії мають однаковий жировий склад`}},{id:`b`,text:{en:`Foods usually contain mixtures of fatty acids`,ua:`Продукти зазвичай містять суміші жирних кислот`}},{id:`c`,text:{en:`Fat provides approximately 9 kcal per gram`,ua:`Жир дає приблизно 9 ккал на грам`}},{id:`d`,text:{en:`Many vegetable oils contain unsaturated fats`,ua:`Багато рослинних олій містять ненасичені жири`}}],answer:{optionIds:[`b`,`c`,`d`]}}];var n={theoryId:230,exercises:i};export{n as default,i as exercises,a as theoryId};